// GET  /api/device?deviceId=…  — the device's settings (created on first use).
// POST /api/device { deviceId, ownerName, message } — saves them.
// The deviceId is a random UUID generated by the app and never shown, so it works as the
// device's key together with the app token.
import { isAlertId as isUuid } from '../lib/alertModel.js'
import { cleanText, MAX_MESSAGE_LENGTH, MAX_NAME_LENGTH } from '../lib/contactModel.js'
import { ensureDevice, updateDevice } from '../lib/contactStore.js'
import { errorResponse, isAuthorized, json, preflight, readJsonBody, withCors } from '../lib/http.js'

async function handleGET(request: Request): Promise<Response> {
  if (!isAuthorized(request)) return errorResponse('Unauthorized', 401)
  const deviceId = new URL(request.url).searchParams.get('deviceId')
  if (!isUuid(deviceId)) return errorResponse('Invalid deviceId', 400)
  const { ownerName, message } = await ensureDevice(deviceId)
  return json({ ownerName, message })
}

async function handlePOST(request: Request): Promise<Response> {
  if (!isAuthorized(request)) return errorResponse('Unauthorized', 401)
  const body = await readJsonBody(request)
  if (!body || !isUuid(body.deviceId)) return errorResponse('Invalid deviceId', 400)
  // Both fields may be cleared with an empty string.
  const ownerName = body.ownerName === '' ? '' : cleanText(body.ownerName, MAX_NAME_LENGTH)
  const message = body.message === '' ? '' : cleanText(body.message, MAX_MESSAGE_LENGTH)
  if (ownerName === null || message === null) return errorResponse('Invalid ownerName or message', 400)
  const device = await updateDevice(body.deviceId, { ownerName, message })
  return json({ ownerName: device.ownerName, message: device.message })
}

export const GET = withCors(handleGET)
export const POST = withCors(handlePOST)
export const OPTIONS = withCors(preflight)
